  'person',
  '{"document_kind":"tour_product_full_page_v1","schema_version":7,"slug":"seoul-winter-seoraksan-nami-eobi-ice-valley-day-tour","locale":"ja","product_id":"seoul-winter-seoraksan-nami-eobi-ice-valley-day-tour","seo":{"pageTitle":"ソウル発 冬の日帰りツアー — 雪岳山・南怡島・オビ渓谷の氷壁 | AtoC Korea","metaDescription":"ソウル発、冬季限定のバス日帰りツアー。雪に覆われた雪岳山国立公園、霜をまとった南怡島の並木道、そして加平のオビ渓谷の氷壁を訪ねます。弘大入口駅または明洞駅から乗車、国立公園の入場と南怡島のフェリー込み。","title":"ソウル発 冬の日帰りツアー — 雪岳山・南怡島・オビ渓谷の氷壁","description":"雪に覆われた雪岳山国立公園、南怡島、そして加平の村人が築くオビ渓谷の氷壁を組み合わせた、冬季限定のソウル発日帰りツアーです。","primaryKeywords":["ソウル発 冬 日帰りツアー","オビ渓谷 氷壁","ソウル発 雪岳山 冬 ツアー","南怡島 冬 雪景色","加平 氷壁 日帰り"],"ogImage":"https://www.atockorea.com/images/tours/seoraksan-national-park/seoraksan-ridge-view.webp"},"catalog_card":{"slug":"seoul-winter-seoraksan-nami-eobi-ice-valley-day-tour","title":"ソウル発 冬季限定：雪岳山（ソラクサン）・南怡島（ナミソム）・オビ渓谷の氷壁","subtitle":"冬季限定のバス1日 — 韓国で最も名高い峰の雪、霜をまとった南怡島、そして村がつくる氷壁","region":"ソウル → 江原道 → 京畿道（加平）","duration":"13.5時間","stopsCount":3,"rating":0,"reviewCount":0,"badges":["冬季限定","季節限定","ソウル発日帰り","雪岳山（ソラクサン）","氷壁"],"tags":["冬季限定","季節限定","ソウル発日帰り","雪岳山（ソラクサン）","南怡島（ナミソム）","氷壁"],"heroImage":"/images/tours/seoraksan-national-park/seoraksan-ridge-view.webp","thumbnail":"/images/tours/seoraksan-national-park/seoraksan-ridge-view.webp","priceLabel":"","shortCardDescription":"厳冬期のみの運行です。雪に覆われた雪岳山、霜をまとった南怡島の並木道、そして加平の村人が毎年1月に渓谷の岩肌へ育てる高さ25メートルの氷壁を訪ねます。"},"headlineLine1":"ソウル発 冬の日帰りツアー","headlineLine2":"雪岳山・南怡島・オビ渓谷の氷壁","price":{"amountLabel":"69","currency":"USD","per":"person","salePriceUsd":69},"hero":{"imageUrl":"/images/tours/seoraksan-national-park/seoraksan-ridge-view.webp","imagePosition":"center 40%","images":["/images/tours/seoraksan-national-park/seoraksan-ridge-view.webp"],"tagline":"ソウル発、冬季限定のバスの一日 — 雪をまとった韓国で最もよく知られた国立公園、霜に覆われた南怡島の並木道、そして加平のある村が毎年1月に手作業で築く高さ25メートルの氷壁","pills":["冬季限定","雪＋氷壁","バス日帰り"],"meta":{"duration":"13.5時間","region":"ソウル → 江原道 → 京畿道（加平）","stops":"3スポット","rating":0,"ratingStars":0}},"subnavItems":[{"id":"overview","label":"概要"},{"id":"itinerary","label":"旅程"},{"id":"details","label":"詳細"},{"id":"faq","label":"FAQ"},{"id":"reviews","label":"口コミ"}],"glanceItems":[{"icon":"clock","label":"所要時間","value":"13.5時間"},{"icon":"camera","label":"フォトジェニック度","value":"非常に高い","level":5},{"icon":"mountain","label":"景観","value":"非常に高い","level":5},{"icon":"footprints","label":"徒歩量","value":"普通","level":3},{"icon":"cloud-rain","label":"天候の影響度","value":"高い","level":2},{"icon":"users","label":"ファミリー向け度","value":"普通","level":3},{"icon":"gauge","label":"ペース","value":"ぎっしり","level":4}],"galleryItems":[{"id":1,"type":"photo","src":"/images/tours/seoraksan-national-park/seoraksan-ridge-view.webp","location":"雪岳山国立公園","caption":"雪岳山国立公園 — photo 1","alt":"雪岳山国立公園 — gallery image 1"},{"id":2,"type":"photo","src":"/images/tours/seoraksan-national-park/seoraksan-sinheungsa-ulsanbawi.webp","location":"雪岳山国立公園","caption":"雪岳山国立公園 — photo 2","alt":"雪岳山国立公園 — gallery image 2"},{"id":3,"type":"photo","src":"/images/tours/seoraksan-national-park/seoraksan-gwongumseong-cable-car.webp","location":"雪岳山国立公園","caption":"雪岳山国立公園 — photo 3","alt":"雪岳山国立公園 — gallery image 3"},{"id":4,"type":"photo","src":"/images/tours/seoraksan-national-park/seoraksan-sinheungsa-ulsan-rock.webp","location":"雪岳山国立公園","caption":"雪岳山国立公園 — photo 4","alt":"雪岳山国立公園 — gallery image 4"},{"id":5,"type":"photo","src":"/images/tours/nami-island/nami-metasequoia-sunset-lake.webp","location":"南怡島（ナミソム）","caption":"南怡島（ナミソム） — photo 1","alt":"南怡島（ナミソム） — gallery image 1"},{"id":6,"type":"photo","src":"/images/tours/nami-island/kakaotalk-20260510-222949305-04.webp","location":"南怡島（ナミソム）","caption":"南怡島（ナミソム） — photo 2","alt":"南怡島（ナミソム） — gallery image 2"},{"id":7,"type":"photo","src":"/images/tours/nami-island/kakaotalk-20260510-222949305-05.webp","location":"南怡島（ナミソム）","caption":"南怡島（ナミソム） — photo 3","alt":"南怡島（ナミソム） — gallery image 3"},{"id":8,"type":"photo","src":"/images/tours/nami-island/chatgpt-image-2026-5-11-01-12-05.webp","location":"南怡島（ナミソム）","caption":"南怡島（ナミソム） — photo 4","alt":"南怡島（ナミソム） — gallery image 4"}],"itineraryStops":[{"number":1,"time":"06:00 / 06:30","duration":"30分の受付枠","name":"乗車（弘大入口駅または明洞駅）","category":"バス乗車","description":"乗車場所はソウル市内の2か所のいずれかです：**（1）スターバックス 弘大入口駅8番出口店（麻浦区）** 06:00 — スターバックスの店舗は8番出口を上がってすぐの場所にあります。または **（2）明洞駅2番出口（中区）** 06:30 — 出口の隣にあるノースフェイスの旗艦店が目印です。\n\n2か所とも同じ暖房付きバスに乗車し、弘大入口の乗客が先に乗ります。ご希望の乗車場所に**予定時刻の5分前**までにお越しください — 寒い朝の早い出発で、09:30までに雪岳山へ着けて初めて成り立つ一日です。\n\n地下鉄までの道のりではなく、一日全体に合わせた服装で乗車してください。3か所のうち2か所では−5 °C以下の屋外に立つことになり、最後の1か所は氷の上です。ガイドは韓英併記の行程カードをお渡しし、雪岳山のケーブルカーが運行しているか、オビで村がいくら徴収するかを含め、その日の計画を確認します。","image":null,"highlights":[],"timeUsed":["ご希望の乗車場所に、予定時刻の5分前までに到着（約5分）","目印のスターバックス／ノースフェイス前で、AtoC Koreaのバスを確認（約5分）","乗車列に並んで乗車（約10分）","乗車時に韓英併記の行程カードを配布"],"whyOnRoute":"2か所の乗車地点は、ソウルの主要な訪問客エリア2つ — 麻浦区の弘大エリアと中区の明洞 — をカバーし、北東へ向かう行程では弘大入口が先という順序が自然です。06:00発は余裕を見た時間ではありません。雪岳山までは約3時間、そして冬にそこへ行く価値は、光がまだ雪に当たっているうちに谷底に立つことにあります。出発が遅ければ、公園の見学は平板な午後の光の中になり、最後の立ち寄り先も日没後に押し出されてしまいます。","_poi_meta":null,"images":[],"imageCredits":[],"galleryItems":[]},{"name":"雪岳山国立公園","time":"≈ 09:30","number":2,"category":"大韓民国国立公園 — 韓国3大名山のひとつ（1,708m）・ユネスコ生物圏保全地域","duration":"120分（2時間）","timeUsed":["雪岳洞入口に到着＋ドライバーガイドによるオリエンテーション（約10分）","統一大仏＋神興寺まで徒歩（メイン駐車場から約15〜20分）","オプション：権金城へのケーブルカー（待ち時間含む約30〜45分）または飛仙台への散策（約90分）","写真撮影＋車両への集合（約15分）","オプション：神興寺近くの樹齢800年の松の木での写真撮影（約5分）"],"_poi_meta":{"poi_key":"seoraksan_national_park","verified":true,"match":"single_poi","kb_version":"1.27","verified_date":"2026-04-29","sources":["Korea Tourism Organization (VisitKorea — Seoraksan National Park (Outer Seorak) listing + IUCN Green List confirmation)","IUCN Green List of Protected and Conserved Areas (iucngreenlist.org — Seoraksan official entry + 2014 designation + 398.24 km² area)","Korea National Park Service (KNPS — Seoraksan National Park Office official site + endangered species management plan)","UNESCO World Heritage Centre (Mt. Sorak Biosphere Reserve 1982 designation + tentative World Heritage listing)","Wikipedia (Seoraksan National Park — corpus on 30 peaks, 2,000+ animal species, 1,400+ plant species)"]},"highlights":["韓国第5の国立公園(1970年)で唯一のユネスコ生物圏保存地域(1982年8月)","統一大仏: 14.6m / 108トン青銅 — 世界最大級の坐像青銅仏(1997年)","Replace 新興寺 → 神興寺 to match glossary and accurate Hanja.","オプション 雪岳山ロープウェイ1,132mで権金城プラットフォーム(700m、1253年伝説)","30峰、2,000以上の動物種、1,400~1,562の植物種、希少野生動物(ジャコウジカ、ゴーラル、ツキノワグマ)","公園入場料は2023年5月廃止で無料（以前3,500ウォン）、ロープウェイは引き続き有料","**2005年からIUCNカテゴリーII(国立公園)+2014年からIUCN保護地域グリーンリスト** — 五台山・智異山と並びパイロットフェーズで初めてグリーンリスト入りした韓国国立公園","**1982年8月から韓国唯一のユネスコ生物圏保存地域** + **ユネスコ世界遺産暫定リスト掲載** — 韓国の他の国立公園に類例のない複合認定","**ヒマラヤゴーラル保全の中核**: 約260頭の安定個体群(IUCNレッドリストで危急種) — 公園は絶滅危惧種のため特別保護区10カ所、計39km²(公園総面積の10%)を管理"],"smartNotes":{"photo":"雪をかぶった花崗岩を背にした青銅の統一大仏が、この場所の一枚です。冬の晴れた朝には、入口広場から蔚山岩（ウルサンバウィ）の稜線が見えるのが普通です。","facilities":"小公園入口にビジターセンター、カフェ、レストラン、土産物店があります。混み合う冬の日は、屋内で暖をとれる場所が限られます。","tip":"ケーブルカーを前提に予定を立てないでください。冬季は運行時間が日ごとに変わり、他の季節より風と氷で運休することが多く、晴れた日は行列が長くなることもあります。あくまで運が良ければ、という位置づけでお考えください。麓は−5 °Cから+5 °C、体感はさらに低くなる想定の服装で。"},"whyOnRoute":"雪岳山を最初に置くのは、ここが最も遠く、かつ最も光に左右される立ち寄り先だからです。09:30の時点では、花崗岩の稜線に積もった雪はまだきれいで、谷にも雲がかかっていません。3時間かけて向かう理由は、まさにそこにあります。小公園入口での2時間は、青銅の統一大仏、神興寺、そして下部の渓谷路を冬のペースで歩くには十分ですが、登頂には足りません。これは意図的なものです。最初に向かうことで、この日いちばん長い移動を、誰も疲れず、冷えきらないうちに済ませられます。","convenience":{"restroom":"Glossary ''Sinheungsa Temple'' → 神興寺. Translator used WRONG kanji 新興寺 (新 = new) instead of correct 神興寺 (神 = god, matches Korean Hanja 神興). Replace 新興寺 → 神興寺 across all 3 occurrences.","parking":"小公園メインゲートに駐車場(有料)"},"description":"**雪岳山**は**韓国第5の国立公園**で1970年3月に指定、1982年8月にはその卓越した山岳生物多様性によりユネスコ生物圏保存地域として認定された、**韓国唯一の同認定地**です。公園は4市郡にまたがる約398km²、30の名峰を擁し、最高峰は**大青峰(1,708m、韓国第3位)**、有名な**蔚山岩(ウルサンバウィ)**の6本柱の花崗岩岩塊もここにあります。公園入場料は無料 — **神興寺**に代わって徴収されていた3,500ウォンの料金が2023年5月に廃止されました(現在は公的資金で寺院を維持)。\n\n小公園(外雪岳)メインゲートからの典型的な3時間訪問は3つのハイライトを網羅します: **統一大仏**(高さ14.6m、108トンの青銅で世界最大級の坐像青銅仏、1997年に韓国統一を祈念して建立、内部に観音菩薩堂)、神興寺(西暦652年に新羅時代の慈蔵律師が創建した世界最古の禅(ソン)寺院で曹渓宗の総本山)、オプションの**雪岳山ロープウェイ**(片道約10分、1,132mで標高700mの権金城プラットフォームへ — **大人往復16,000ウォン / 子ども12,000ウォン**、現地販売のみで予約不可、10月の紅葉ピーク時は数時間待ちもあり)。\n\n山頂の権金城には鮮やかな伝説 — 1253年のモンゴル軍による高麗侵攻時、権・金という2人の将軍が一日で築いたとされる名前の由来があります。ロープウェイを使わない健脚派には、1.5kmの飛仙台渓流脇散策(ほぼ舗装路)、揺れ岩のループ(片道1.5時間、石段あり)、600mの金剛窟洞窟登り(往復約1時間40分)などのコースもあります。","visitBasics":{"hours":"国立公園は通年開放、神興寺は06:00から。権金城ケーブルカーは冬も運行しますが、運行時間は天候により日ごとに変わり、強風や凍結時には運休します。運営者が毎朝その日のスケジュールを掲示するため、運行は保証されません","closed":"通年開園。ただし高所のトレイルは防火・安全のため季節休止となり、通常は11月中旬から12月中旬まで、および2月中旬ごろから閉鎖されます。この行程では入口近くの低い渓谷路のみを使うため、影響はありません","admission":"国立公園の入場は無料（₩3,500の料金は2023年5月に廃止）。ケーブルカー往復は大人₩16,000、現地販売のみ。本ツアーには含まれておらず、運行も保証されません","walking":"谷底は易しい〜普通 — 神興寺と統一大仏へは舗装路と階段が続き、場所によっては雪で滑ります。登山の予定はありませんが、滑りにくい丈夫な靴が必須です"},"image":"/images/tours/seoraksan-national-park/seoraksan-ridge-view.webp","images":["/images/tours/seoraksan-national-park/seoraksan-ridge-view.webp","/images/tours/seoraksan-national-park/seoraksan-sinheungsa-ulsanbawi.webp","/images/tours/seoraksan-national-park/seoraksan-gwongumseong-cable-car.webp","/images/tours/seoraksan-national-park/seoraksan-sinheungsa-ulsan-rock.webp"],"imageCredits":[{"url":"/images/tours/seoraksan-national-park/seoraksan-ridge-view.webp","source":"atoc-korea"},{"url":"/images/tours/seoraksan-national-park/seoraksan-sinheungsa-ulsanbawi.webp","source":"atoc-korea"},{"url":"/images/tours/seoraksan-national-park/seoraksan-gwongumseong-cable-car.webp","source":"atoc-korea"},{"url":"/images/tours/seoraksan-national-park/seoraksan-sinheungsa-ulsan-rock.webp","source":"atoc-korea"}],"galleryItems":[{"id":1,"type":"photo","src":"/images/tours/seoraksan-national-park/seoraksan-ridge-view.webp","location":"雪岳山国立公園","caption":"雪岳山国立公園 — photo 1","alt":"雪岳山国立公園 — gallery image 1"},{"id":2,"type":"photo","src":"/images/tours/seoraksan-national-park/seoraksan-sinheungsa-ulsanbawi.webp","location":"雪岳山国立公園","caption":"雪岳山国立公園 — photo 2","alt":"雪岳山国立公園 — gallery image 2"},{"id":3,"type":"photo","src":"/images/tours/seoraksan-national-park/seoraksan-gwongumseong-cable-car.webp","location":"雪岳山国立公園","caption":"雪岳山国立公園 — photo 3","alt":"雪岳山国立公園 — gallery image 3"},{"id":4,"type":"photo","src":"/images/tours/seoraksan-national-park/seoraksan-sinheungsa-ulsan-rock.webp","location":"雪岳山国立公園","caption":"雪岳山国立公園 — photo 4","alt":"雪岳山国立公園 — gallery image 4"}]},{"number":3,"time":"≈ 11:45","duration":"50分","name":"束草（ソクチョ）近郊での昼食（各自負担）","category":"昼食休憩","description":"国立公園のあと、雪岳山周辺または束草側の地元レストランで約50分停車します。昼食は**含まれていません** — お好きなものを注文してお支払いいただきます。目安は1人あたり₩10,000〜15,000です。\n\nここは東海岸の海鮮地帯なので、地元の選択肢は**フェドッパプ**（刺身をのせたご飯）、焼き魚、あるいは**スンドゥブチゲ** — 束草の草山（チョクサン）地区で知られる柔らかい豆腐の鍋で、雪の中を2時間歩いたあとにちょうどよい一皿です。ベジタリアン向けの選択肢は限られます。朝のうちにガイドへお伝えいただければ、事前に店へ連絡します。\n\n現金かカードをお持ちください。50分という短さは意図的なものです — 西の南怡島までは2時間の移動があり、残る2か所はどちらも日中の明るさを必要とします。","image":null,"highlights":[],"timeUsed":["バスが駐車し、ガイドがレストランまで案内（約5分）","注文と食事（約35分）","各自で会計を済ませ、バスに集合（約10分）"],"whyOnRoute":"昼食が雪岳山の直後にあるのは、一日のうちで、腰を据えた食事が明るい時間を削らない唯一の場面だからです。これ以降はすべて時間に追われます。南怡島は並木道のために光が要り、オビは村の見学エリアが閉まる前に着く必要があります。ここで食事をとることは、その日いちばん寒い歩行の直後に体を温めることにもなります。","_poi_meta":null,"images":[],"imageCredits":[],"galleryItems":[]},{"name":"南怡島（ナミソム）","time":"≈ 14:35","number":4,"category":"加平郡の河中島 — 「冬のソナタ」ロケ地・ポプラ並木","duration":"120分（2時間）","timeUsed":["加平桟橋からフェリーで渡る（待ち時間含む5〜10分）","メタセコイア／イチョウ／チョウセンゴヨウの並木道を自由散策 — 島の半周コース約3km","オプション：自転車レンタル（シングル7,000ウォン／タンデム14,000ウォン、1時間あたり）または電気式ブルートレイン（ユニセフホールまで片道3,000ウォン）","島内での軽食休憩（ソナタカフェ、ホットク、さつまいもラテ）","本土へ戻るフェリーに乗船"],"_poi_meta":{"poi_key":"nami_island","verified":true,"match":"single_poi","kb_version":"1.27","verified_date":"2026-04-29","sources":["Korea Tourism Organization (VisitKorea — Nami Island official listing + visa fee schedule)","Naminara Republic Official Site (namisum-en.imweb.me — own corpus on cultural-independence brand)","UNICEF Korea (Nami Island 2010 Child Friendly Park designation + International Children''s Book Festival)","KBS / Korea Times (Winter Sonata 2002 production retrospectives + Japanese tourism boom coverage)","Wikipedia (Namiseom — open corpus on General Nami history + Cheongpyeong Dam 1944 origin)"]},"highlights":["**「冬のソナタ」（2002年）**のロケ地 — 東アジアKドラマ聖地","**メタセコイア・ポプラ並木** — 秋の黄金色の落葉が絶景","春：菜の花畑。夏：緑のトンネル。秋：紅葉。冬：雪景色 — **4シーズン対応**","加平港からフェリーで5〜10分（**フェリー代金含まれます**）","年間約**200万人**が訪れる東アジアのKドラマ観光地"],"smartNotes":{"photo":"メタセコイア並木 — 秋の黄金色と冬の雪景色が代表的なショット。","facilities":"島内に韓屋風レストラン、カフェ、お土産店。","tip":"ベストシーズン：春（4〜5月桜）、秋（10月黄金のイチョウ）。週末ピーク時は早めの到着を。"},"whyOnRoute":"南怡島がこの一日の中盤にあるのは、日中の明るさと船の両方が必要な唯一の立ち寄り先だからです。冬にわざわざ渡る価値があるのは霜をまとったメタセコイアとイチョウの並木道で、それには光が要ります。またフェリーの甲板は吹きさらしなので、午後半ばの渡河は遅い時間より快適です。雪岳山のあとに置くことで、西へ戻る長い移動を1本ではなく、扱いやすい2本に分けられます。","convenience":{"restroom":"島内複数か所＋カピョン桟橋","parking":"カピョン桟橋 小型車₩6,000/大型車₩10,000"},"description":"**南怡島**は京畿道加平郡の北漢江に浮かぶ**半月形の河中島（周囲4.6km）**で、**朝鮮王朝第7代王の庶子・南怡将軍**にちなんで名付けられた。1965年に春川ダム建設で生まれた人工島。日本での「**冬のソナタ****」（2002年、KBS）の爆発的ヒット**以降、東アジアのKドラマツーリズムの聖地として知られ、韓国国内外から年間**約200万人**が訪れる。\n\n最も有名な景観は**メタセコイアのポプラ並木** — 秋の黄金色の落葉が絶景。また、** （ロシアオリーブ）の並木**・**（菜の花）畑**・**（コスモス）畑**など、季節ごとに異なる絵画的な風景が島内各所に広がります。島内を自転車で回ることも可能（レンタル有料）。加平港からフェリーで5〜10分（フェリー代金はツアーに含まれます）。","visitBasics":{"hours":"フェリーは08:00から、最終便の入島は21:00、日中はおおむね10〜20分間隔。島内の店舗の多くは18:00までに閉まります。冬季のスケジュールは天候により変わることがあります","closed":"通年営業","admission":"ナミナラ共和国ビザ料金（往復フェリー込み）：大人 ₩19,000 — 本ツアーに含まれます","walking":"易しい — 平坦な並木道ですが、真冬は足元が凍っていることがあります。半周で約3 km。島内では自転車と電動カートを各自負担でレンタルできます"},"image":"/images/tours/nami-island/nami-metasequoia-sunset-lake.webp","images":["/images/tours/nami-island/nami-metasequoia-sunset-lake.webp","/images/tours/nami-island/kakaotalk-20260510-222949305-04.webp","/images/tours/nami-island/kakaotalk-20260510-222949305-05.webp","/images/tours/nami-island/chatgpt-image-2026-5-11-01-12-05.webp"],"imageCredits":[{"url":"/images/tours/nami-island/nami-metasequoia-sunset-lake.webp","source":"atoc-korea"},{"url":"/images/tours/nami-island/kakaotalk-20260510-222949305-04.webp","source":"atoc-korea"},{"url":"/images/tours/nami-island/kakaotalk-20260510-222949305-05.webp","source":"atoc-korea"},{"url":"/images/tours/nami-island/chatgpt-image-2026-5-11-01-12-05.webp","source":"atoc-korea"}],"galleryItems":[{"id":1,"type":"photo","src":"/images/tours/nami-island/nami-metasequoia-sunset-lake.webp","location":"南怡島（ナミソム）","caption":"南怡島（ナミソム） — photo 1","alt":"南怡島（ナミソム） — gallery image 1"},{"id":2,"type":"photo","src":"/images/tours/nami-island/kakaotalk-20260510-222949305-04.webp","location":"南怡島（ナミソム）","caption":"南怡島（ナミソム） — photo 2","alt":"南怡島（ナミソム） — gallery image 2"},{"id":3,"type":"photo","src":"/images/tours/nami-island/kakaotalk-20260510-222949305-05.webp","location":"南怡島（ナミソム）","caption":"南怡島（ナミソム） — photo 3","alt":"南怡島（ナミソム） — gallery image 3"},{"id":4,"type":"photo","src":"/images/tours/nami-island/chatgpt-image-2026-5-11-01-12-05.webp","location":"南怡島（ナミソム）","caption":"南怡島（ナミソム） — photo 4","alt":"南怡島（ナミソム） — gallery image 4"}]},{"number":5,"time":"≈ 16:45","duration":"45分","name":"オビ渓谷の氷壁","category":"冬の村の祭り（季節限定）","description":"オビ渓谷 — 어비계곡、かつて水の流れが速く、魚が飛んでいるように見えたことから「魚飛」の字が当てられました — は、加平南部の雪岳面（ソラクミョン）にある全長3キロの渓谷です。夏には水遊びとマス釣りの川になります。冬には、他の季節からはまったく想像のつかないものに変わります。\n\n**ここの氷壁は、見つかったものではなく、つくられたものです。** 2023年の冬以来、加日（カイル）2里の住民が最も寒い数週間のあいだ渓谷の岩肌に水を撒き、あとは寒さに任せて、高さ**約25メートル**と伝えられる氷の面に育て上げてきました。運営しているのは村の住民自治会 — およそ30人 — で、それまで冬の来訪者がほとんどいなかった渓谷にとっての、オフシーズンの収入事業です。公的な観光ページを含め、これを自然の氷瀑と説明している媒体もあります。そうではありません。そして、そうでないからこそ見応えがあります。\n\n見学は渓谷沿いの**木製デッキ通路**からです。これは京畿道の渓谷整備事業の一環で、夜間照明もこのときに設置されました。**氷壁の真下の地面は立ち入り禁止です** — そこで滑って負傷した方が出たためで、写真は真下からではなく、指定の見学エリアから撮ることになります。氷壁のそばでは、村が氷のそり滑り、回転式のスノーそり、イグルーのフォトゾーン、暖房付きの小さな温室庭園を運営しています。\n\n到着は夕方で、村が公表している祭り会場の営業時間の終わりごろにあたります。厳冬期には、氷に当たる最後の日ざしを見ることになります。写真には良く、そして寒いです。最盛期には村がデッキの照明を灯しますが、点灯は営業終了のころになるため、この行程では照明をお約束していません。見学エリアとそり体験には、村が現地で少額の料金を徴収します。金額は地元で決められ、年ごとに変わります。","image":null,"highlights":["2023年の冬から加日2里の村人が渓谷の岩肌に育ててきた、高さ約25 mと伝えられる氷壁 — 自然のものではなく、つくられたものです","村の住民自治会（約30人）がオフシーズンの事業として運営。名称は어비계곡 겨울나라（オビ渓谷ウィンターランド）","京畿道の清浄渓谷整備事業で設けられた、夜間照明付きの木製デッキ見学路","氷壁のそばには氷のそり滑り、回転式スノーそり、イグルーのフォトゾーン、暖房付きの温室庭園","渓谷の名前 어비（魚飛）は「飛ぶ魚」の意 — かつて水の流れが速く、魚が飛んでいるように見えたことに由来します","評判が広がるにつれ来訪者はおよそ倍増し、1シーズンで約60,000人に。多くは東南アジアからの旅行者です"],"timeUsed":["バスが駐車し、ガイドが渓谷の入口まで案内（約10分）","デッキ通路を通って氷壁の見学エリアへ、そして撮影（約25分）","希望に応じてそり滑りや温室庭園へ、または早めにバスへ戻って暖をとる（約10分）"],"whyOnRoute":"オビが一日の締めくくりになるのには、2つの理由があります。地理的には、このルートで唯一ソウル側にある立ち寄り先だからです — 雪岳面は加平南部、すでに家路を向いた位置にあるため、長い一日の最後にここで1時間過ごしても、余分な走行は発生しません。編集上の理由としては、この行程が通年ではなく冬の商品である理由そのものだからです。雪岳山と南怡島はどの季節でも訪ねられますが、氷壁が存在するのはおそらく8週間ほど、しかも寒さが続いた場合に限られます。またここは、多くの旅行者が名前すら聞いたことのない立ち寄り先でもあり、締めくくりとしてふさわしい場所です。","_poi_meta":{"match":"authored","poi_key":"eobi_ice_valley","sources":["京仁日報（경인일보）— 加平オビ渓谷の인공빙벽（人工氷壁）と、それを運営する加日2里住民自治会に関する報道","加平郡観光課（gptour.go.kr）— オビ渓谷の掲載情報、雪岳面加日里","韓国観光公社（VisitKorea — オビ渓谷の掲載情報。ただし韓国観光公社の英語表記はこの氷壁を自然のものと説明しており、韓国語の記録はこれと矛盾します）","어비계곡 겨울나라 公式の祭り情報 — シーズンの日程、現地料金、アクティビティ","京畿道 清浄渓谷整備事業（청정계곡 정비사업）— デッキ通路と夜間照明"],"verified":true,"verified_date":"2026-08-04"},"smartNotes":{"photo":"撮影はデッキの指定見学エリアから — 氷壁の下は柵で仕切られています。夕方は氷に残る日ざしと、そのあとのデッキ照明の両方が使えます。どちらも良く、その切り替わりの時間帯が最良の枠です。","facilities":"村の運営で設備は簡素です。暖房付きの温室庭園、そりの斜面、小さな売店があります。しっかりした食事や、広い屋内の暖房スペースは期待しないでください。","tip":"滑りにくい冬用の靴を履き、氷壁は保証されたものではなく天候次第のものとお考えください — 暖かい日が続けば縮みますし、開場は村が自ら決めます。現地の料金用に、少額の現金をお持ちください。"},"visitBasics":{"hours":"村の運営による季節営業です。村が公表している祭り会場の営業時間は10:00〜17:00です（オビ渓谷村、031-585-3551）。この行程はその終わりごろに到着するため、有料の体験はすでに片づけに入っていることがあります。渓谷と木道自体は入場を管理する施設ではありません。営業時間は毎年地元で決められます","closed":"冬季のみ — 暫定で12月中旬から2月中旬までです。日程は毎年村が決めるため、確定した予定表ではなく目安です。2025-26シーズンは12月20日から2月19日まで運営され、2026-27の日程はまだ発表されていません。氷壁は寒さが続いて初めて現れ、1月と2月上旬が最も確実です","admission":"含まれません。氷壁の見学エリアは村が1人あたり約₩1,000を徴収し、そりや体験のパスはおおむね₩5,000〜30,000で別料金です。村の入口の駐車場は無料で、そこから渓谷の木道を約500m歩いて会場に向かいます。料金は地元で決められ、年ごとに変わります。その日の料金はガイドが車内で確認します","walking":"距離は短いものの、実際にかなり滑ります。見学エリアまではほぼ平坦な木製デッキ通路ですが、その手前と周辺は滑りやすく、滑りにくい靴が必須です。氷壁の真下は立ち入り禁止です。車椅子・ベビーカーには適しません"},"images":[],"imageCredits":[],"galleryItems":[]},{"number":6,"time":"≈ 19:00","duration":"約1.5時間の走行","name":"ソウルへ帰着（明洞駅または弘大入口駅）","category":"帰着・降車","description":"オビ渓谷発は17:30ごろ。ソウルまで約1.5時間の道のりです。降車は乗車と逆の順序で、**明洞駅に19:00ごろ**、続いて**弘大入口駅に19:30ごろ**です。\n\nどちらも地下鉄の乗換駅です。この区間で最も変動するのは冬の路面状況で、加平の道の積雪や、金曜・日曜夕方の渋滞で30〜60分ほど余計にかかることがあります。その日の見込みは、ガイドが車内でお伝えします。長い一日ですので、この区間は多くの方が眠って過ごされます。","image":null,"highlights":[],"timeUsed":["オビ渓谷発（17:30ごろ）","高速道路をソウルへ走行（約1.5時間、積雪や週末の渋滞時はさらに長く）","明洞駅で降車（19:00ごろ）","弘大入口駅で降車（19:30ごろ）"],"whyOnRoute":"オビで終えることが、帰路を短く保っています。この渓谷はこのルートでソウルに最も近い立ち寄り先で、出発した瞬間からバスは家路を向いています。降車の順序を逆にすることで、最後に乗った明洞の方が最初に降りられます。","_poi_meta":null,"images":[],"imageCredits":[],"galleryItems":[]}],"routeFlowStops":[{"name":"乗車（弘大入口／明洞）","type":"origin","theme":"Seoul pickup"},{"name":"雪岳山国立公園","type":"primary","theme":"Winter mountain"},{"name":"束草近郊で昼食","type":"secondary","theme":"Lunch break"},{"name":"南怡島（ナミソム）","type":"primary","theme":"K-drama island"},{"name":"オビ渓谷の氷壁","type":"primary","theme":"Ice wall"},{"name":"ソウルへ帰着","type":"return","theme":"Drop-off"}],"routePhases":[{"phase":"ソウル → 雪岳山（ソラクサン）","duration":"約3.5時間","description":"06:00に弘大入口駅、06:30に明洞駅で乗車し、ソウル-襄陽高速道路を北東へ約3時間。途中で休憩を1回挟み、09:30ごろに小公園（ソゴンウォン）入口へ到着します。"},{"phase":"雪岳山（ソラクサン）","duration":"約2時間","description":"小公園入口での自由行動：青銅の統一大仏、神興寺、そして雪に覆われた下部の渓谷路。ケーブルカーは含まれておらず、風と氷の状況が許すときのみ運行します。"},{"phase":"昼食 → 南怡島（ナミソム）","duration":"約3時間","description":"束草近郊で昼食（各自負担）。その後、西へ約2時間戻って加平船着場へ。5分のフェリーで南怡島へ渡り、霜をまとったメタセコイア並木の中で2時間過ごします。"},{"phase":"オビ渓谷 → ソウル","duration":"約2.5時間","description":"南へ40分走ってオビ渓谷へ。夕方の光の中で氷壁を見学し、その後、約1.5時間かけてソウルへ — 明洞は19:00ごろ、弘大入口は19:30ごろです。"}],"routeShapeIntro":{"title":"この冬の一日はこう動きます","subtitle":"06:00に弘大入口駅、06:30に明洞駅を出発し、北東へ約3時間。雪がまだきれいで、花崗岩に光が当たっている午前中に雪岳山へ着きます。束草近郊で昼食をとったあと、春川方面を通って西へ長い距離を戻り、南怡島で霜をまとった並木道を歩きます。最後のオビ渓谷は加平南部にあり、すでにソウルを向いた位置です。村の営業時間が終わりに近づく夕方に到着します。ソウルには19:00〜19:30ごろ帰着します。"},"whyTourWorks":{"bestFor":["1月・2月に韓国を訪れ、都市ではなく冬の風景を見たい方","花崗岩に積もった雪、霜をまとった並木道、ブルーアワーの氷壁を撮りたい方","長く、寒く、内容の詰まった一日を受け入れられるカップルや少人数のグループ","ソウル発の日帰りツアーではあまり扱われないものを見たい方"],"lessIdealFor":["冬季以外に旅行される方 — 暖かい時期に氷壁は存在しません","寒さに弱い方、天候にかかわらず確実な観光を必要とされる方","歩行を最小限にしたい方 — 凍った路面と、最後の立ち寄り先のデッキ通路があります","小さなお子さま、冬の路面で足元が不安な方"],"routeLogicSections":[{"title":"ペースと地理","icon":"route","iconBg":"bg-sky-50/80","iconColor":"text-sky-600","items":[{"label":"まず雪岳山へ、雪がまだきれいなうちに","detail":"国立公園はこの一日で最も遠く、午後の融雪と雲の影響を最も受ける場所です。最初に向かうことで、最も澄んだ光と最も新しい雪に当たりますし、長い移動を誰も疲れていないうちに済ませられます。"},{"label":"南怡島は中盤に、フェリーには日中の明るさが要るから","detail":"冬の南怡島の見どころは霜をまとった並木道で、そこには光が要ります。午後半ばの枠なら、島がまだ明るいうちに渡れますし、吹きさらしのフェリー甲板で風が強まる前に済みます。"},{"label":"オビは最後に、すでに帰り道にあるから","detail":"オビ渓谷は加平南部の雪岳面（ソラクミョン）にあり、このルートのどこよりもソウル寄りです。ここで終えれば引き返す必要がなく、厳冬期には遅い到着がちょうど、デッキ通路沿いの夜間照明が灯る時間と重なります。"},{"label":"ひとつの短い季節のために組まれたルート","detail":"氷壁は寒さが続くあいだしか存在しません。村が12月中旬から築き始め、2月には取り壊されます。この行程が存在する理由も、一年の残りを運行しない理由も、その一点にあります。"}]}]},"practicalAccordionItems":[{"id":"pickup","title":"乗車・降車場所","preview":"ソウル市内の乗車地点2か所：スターバックス 弘大入口駅8番出口店 06:00（麻浦区）、明洞駅2番出口・ノースフェイス旗艦店前 06:30（中区）。","content":["ソウル市内の乗車地点2か所：スターバックス 弘大入口駅8番出口店 06:00（麻浦区）、明洞駅2番出口・ノースフェイス旗艦店前 06:30（中区）。","2か所とも同じバスに乗車します。ご希望の場所に5分前までにお越しください。","帰りの降車は逆順で、明洞 ≈19:00、弘大入口 ≈19:30。","実際のツアー所要時間は乗車場所によって異なります：弘大入口から≈13.5時間、明洞から≈12.5時間。"]},{"id":"what-to-bring","title":"服装と持ち物","preview":"滑りにくい冬用の靴 — 最も重要な一品です。3か所すべてで足元に氷があります。","content":["滑りにくい冬用の靴 — 最も重要な一品です。3か所すべてで足元に氷があります。","きちんとした防寒の重ね着：雪岳山では−5 °C以下、強い体感冷えを想定してください。オビでは夕暮れ時の冷え込みがあります。","手袋、帽子、そして耳を覆えるもの。南怡島のフェリー甲板は完全に吹きさらしです。","オビの村営料金と昼食（₩10,000〜15,000）のための少額の現金。","カメラかスマートフォン、そして予備バッテリー — 寒さでバッテリーは早く減りますし、このルートは皆さんがよく写真を撮る道のりです。"]},{"id":"weather-policy","title":"天候について","preview":"これは冬季のツアーであり、天候は例外ではなく商品の一部です。","content":["これは冬季のツアーであり、天候は例外ではなく商品の一部です。","オビの氷壁は保証されていません。 最も寒い数週間をかけて村人が築くもので、暖かい日が続けば縮んだり、なくなったりします。開場は村が自ら決めます。ご出発日に見学できない場合は、ご出発前にお知らせし、日程変更またはその分の返金をご案内します。","雪岳山のケーブルカーも保証されていません。 運行時間は日ごとに変わり、強風や凍結時には運休します。料金には含まれていないため、運行しなくても損失は生じません。","大雪：バスは冬用タイヤを装着しており、通常はそのまま運行しますが、帰路が1時間ほど延びることがあります。深刻な積雪や道路閉鎖の場合は出発そのものを中止し、全額返金いたします。","悪天候時は南怡島のフェリーが運休することがあります。その場合、ガイドが他の立ち寄り先の滞在を延ばし、南怡島の入場料は返金します。"]},{"id":"season-window","title":"このツアーの運行時期","preview":"これは冬季限定の行程です。オビ渓谷の氷壁があるから成立するツアーであり、その氷壁は常設のアトラクションではなく、季節限定で村がつくる構造物です。","content":["これは冬季限定の行程です。オビ渓谷の氷壁があるから成立するツアーであり、その氷壁は常設のアトラクションではなく、季節限定で村がつくる構造物です。","氷壁は渓谷の水が凍る12月中旬ごろから形になり始め、1月と2月上旬が最も確実です。","シーズンの終わりは年によって変わります — 2025-26シーズンは2月19日に終了しました。今冬の日程は村が決め、ご予約時に確認します。","シーズン外は、同じ雪岳山と南怡島の組み合わせを、当社の雪岳山＋南怡島＋晨静苑の日帰りツアーで通年ご利用いただけます。"]},{"id":"inclusions","title":"含まれるもの","preview":"ソウル市内2か所の乗車地点と同じ2か所の降車地点、暖房付きバス、有資格の英語ガイド。","content":["ソウル市内2か所の乗車地点と同じ2か所の降車地点、暖房付きバス、有資格の英語ガイド。","雪岳山国立公園の入場 — 2023年5月より無料、チケットは不要です。","南怡島の往復フェリー＋ナミナラ共和国ビザ料金（₩19,000）— 含まれます。","通行料・駐車料金 — 含まれます。","含まれないもの： 昼食と飲み物（₩10,000〜15,000、各自負担）、雪岳山のケーブルカー（大人往復₩16,000、現地販売のみ・天候次第）、オビ渓谷の現地村料金（氷壁の見学エリアは1人あたり約₩1,000、そり体験は別料金）、南怡島の自転車・電動カートのレンタル、その他個人的な出費。","中国語ガイドはご要望に応じて手配できます — 3日前までにご予約ください。"]},{"id":"language","title":"言語","preview":"メインのツアー言語：英語。","content":["メインのツアー言語：英語。","中国語対応ガイドはリクエストにより手配可能 — 3日以上前にご予約ください。","メニュー・看板・屋台でのやり取りには韓国語が使用されますが、ガイドが通訳いたします。"]},{"id":"walking","title":"徒歩と地形","preview":"普通。ここでの難しさは、距離や勾配ではなく氷です。","content":["普通。ここでの難しさは、距離や勾配ではなく氷です。","雪岳山：神興寺と統一大仏へは舗装路と階段が続く渓谷路で、場所によっては雪で滑ります。登山の予定はなく、登頂も行いません。","南怡島：平坦で舗装された並木道を2時間で約3 km。真冬は足元が凍っています。","オビ渓谷：見学エリアまでは短く、ほぼ平坦な木製デッキ通路ですが、その手前と周辺は実際にかなり滑ります。氷壁の下は立ち入り禁止です。","3か所すべてで、滑りにくい冬用の靴が必須です。 この行程では普通のスニーカーでは足りません。オビにはベビーカーと車椅子は適しません。"]},{"id":"lunch","title":"昼食（各自負担）","preview":"昼食は国立公園の直後、11:45ごろに雪岳山周辺または束草側でとります。","content":["昼食は国立公園の直後、11:45ごろに雪岳山周辺または束草側でとります。","東海岸らしい選択肢：フェドッパプ（刺身をのせたご飯）、焼き魚、あるいは束草でよく知られたスンドゥブチゲ（柔らかい豆腐の鍋）。","予算は1人あたりおよそ₩10,000〜15,000。現金・カードとも通常使えます。","停車は50分と短めです — 残る2か所が時間に追われるためです。ベジタリアン向けの選択肢は限られますので、朝のうちにガイドへお伝えください。"]},{"id":"cancellation","title":"キャンセル","preview":"ピックアップの24時間前まで無料でキャンセル可能です。","content":["ピックアップの24時間前まで無料でキャンセル可能です。","24時間以内のキャンセル：50%返金。","無断キャンセルまたはピックアップの見逃し：返金不可 — ただし、ピックアップ予定時刻から10分以内にAtoC Korea運営部門へご連絡いただければ、バスが予定より早く進んでいる場合は少々お待ちいただける場合があります。"]}],"practicalWeatherStatic":{"today":{"temp":"—","label":"季節のご案内をご参照ください"},"tomorrow":{"temp":"—","label":"季節のご案内をご参照ください"},"_seasonalSummary":"Seoul + Gangwon: temperate four-season climate. Seoraksan is 5-7°C cooler than Seoul year-round. Hot humid summers (Jun-Aug), crisp cold winters (Dec-Feb), with prime seasons in spring (April cherry blossoms) and autumn (October-November foliage)."},"seasonalVariations":[{"season":"12月中旬","description":"渓谷の水がしっかり凍ると、氷壁が形になり始めます。シーズン序盤は規模が小さく、村がまだ積み上げている途中のこともあります。雪岳山にはたいてい、その冬の初めての根雪が積もっています。"},{"season":"1月","description":"明らかに最も強い月です。氷壁は最大の高さになり、雪岳山の積雪も最も安定し、南怡島の並木道もしっかり霜をまといます。一年で最も寒い時期ですので、それに応じた服装でお越しください。"},{"season":"2月上旬","description":"多くの年でまだ安定しており、オビでの日照時間もわずかに長くなります。暖かい日が続くと氷壁は急速に縮むため、そこには注意が必要です。"},{"season":"冬季以外","description":"ツアーは運行しません。氷壁は2月下旬までになくなり、オビは夏の水遊びの渓谷に戻ります。冬季以外に雪岳山と南怡島を訪ねたい方は、当社の雪岳山＋南怡島＋晨静苑の日帰りツアーをご覧ください。"}],"bookingTrustItems":[{"icon":"check-circle","title":"入場料すべて込み","description":"南怡島フェリー＋モーニングカームがセット","iconBg":"bg-emerald-50/80","iconColor":"text-emerald-600","body":"南怡島フェリー（₩19,000）とモーニングカーム（₩11,000）の入場料はツアー料金に含まれており、各スポットでのチケット購入は不要です。雪嶽山の入場料は無料（2023年5月廃止）。入場料の総節約額：約₩30,000。"},{"icon":"users","title":"公認英語ガイド付き","description":"韓国公認ツアーガイド","iconBg":"bg-pink-50/80","iconColor":"text-pink-600","body":"韓国観光公社認定の英語堪能なガイドが案内します。中国語対応ガイドは事前リクエストにて手配可能です。ガイドによる解説では、雪嶽山の新羅時代の寺院の歴史、南怡島の「冬のソナタ」にまつわる背景、そしてモーニングカームの創設者のストーリーをご紹介します。"},{"icon":"shield","title":"明瞭な料金体系","description":"隠れたショッピングストップなし","iconBg":"bg-sky-50/80","iconColor":"text-sky-600","body":"高麗人参店への立ち寄りなし、免税店なし、コミッション目的のお土産店への寄り道なし。13.5時間の終日ツアーのすべての時間は、観光地での滞在か移動に充てられます。予約したとおりのご体験をお届けします。"}],"bookingSupportSteps":[{"timing":"即時","title":"即時確認","detail":"ピックアップ場所選択付き予約確認","description":"弘大（ホンデ）・明洞のピックアップ場所選択付き即時予約確認。"},{"timing":"前日","title":"ピックアップ詳細","detail":"WhatsApp／SMSにて正確なピックアップ場所と車両情報をお知らせ","description":"天気確認、コーチのナンバープレート、季節ごとのルートに関する注意事項（アチムコヨ樹木園ライティングフェスティバルの時間、雪岳山の紅葉ピーク時期など）を前日にお送りします。"},{"timing":"当日朝","title":"ピックアップ確認","detail":"出発10分前にピックアップ場所でガイドが確認対応","description":"ガイドは05:50よりスターバックス弘大8番出口前、06:20より明洞2番出口（ノースフェイス前）にてお待ちします。前夜にガイドとコーチの写真をWhatsAppへお送りします。"},{"timing":"ツアー中","title":"ツアー中サポート","detail":"各スポットでのガイドナレーション＋24時間対応オペレーションサポート","description":"ガイドは現地にて解説を行います。雪岳山の西暦652年・新羅時代の開創、ナミ島の1944年・清平ダム建設を起源とする歴史と2002年の「冬のソナタ」の舞台としての遺産、そしてアチムコヨ樹木園の1992年の構想と1996年の開園についてご説明します。"},{"timing":"終日の終わりに","title":"2か所の降車地点","detail":"明洞 約19:00 ／ 弘大 約19:30","description":"コーチは帰路、両ピックアップ地点に逆順で停車します。"},{"timing":"ツアー後","title":"レビュー＆フォローアップ","detail":"任意のツアー後レビュー","description":"ツアー後のフィードバックのお願いをお送りします。ソウル滞在中のレストランや観光スポットに関するご質問には当日中にお答えします。"}],"staticQuestions":[{"question":"オビの氷壁は自然のものですか？","answer":"いいえ — 当日に知っていただくより、先にお伝えしておきます。2023年の冬から、加日2里の村の住民が最も寒い数週間のあいだ渓谷の岩肌に水を撒き、高さ約25メートルと伝えられる氷の面に凍らせてきました。公式の英語ページを含め、一部の観光サイトでは自然の氷瀑と説明されています。それは誤りです。約30人の地元の方々がオフシーズンの収入事業として運営する、村がつくった見どころであり、パンフレットに載っている話よりも良い物語だと私たちは考えています。"},{"question":"氷壁は必ず見られますか？","answer":"いいえ。それを保証するツアーがあれば、それは約束のしすぎです。氷壁は寒さが続くこと、そして村自身が開場を決めることに左右され、暖かい日が続けば縮みます。ご出発日に見学できない場合は、ご旅行前にお知らせし、日程変更またはその分の返金をご案内します。最も確実なのは1月と2月上旬です。"},{"question":"このツアーは正確にはいつ運行しますか？","answer":"冬季のみです。氷壁は通常12月中旬から形になり始め、2025-26シーズンは2月19日に終了しました。正確な日程は毎年、氷壁を築く村が決めます。そのため、守れない固定のカレンダーを公表するのではなく、ご予約時に運行期間を確認しています。"},{"question":"雪岳山のケーブルカーは含まれていますか？","answer":"いいえ。権金城ケーブルカーは大人往復₩16,000で、現地販売のみ、事前予約はできません。冬はとくに、含まれていないことが意味を持ちます。運行時間が日ごとに変わり、強風や凍結時には運休するため、お約束できるものではありません。国立公園の入場自体は2023年5月から無料です。"},{"question":"実際どのくらい寒いですか？","answer":"靴と重ね着で、その日を楽しめるかどうかが決まる程度には寒いです。雪岳山の谷底でおよそ−5 °Cから+5 °C、体感はさらに低く、日陰はもっと冷えます。南怡島のフェリー甲板は完全に吹きさらしです。オビでは、夕暮れどきに氷の壁のそばでじっと立つことになります。手袋、帽子、耳を覆えるものをお持ちください。"},{"question":"どんな靴が必要ですか？","answer":"滑りにくい冬用の靴かブーツです。ここだけは譲れない装備です。3か所すべてで足元に氷があります — 雪岳山の階段のある渓谷路、南怡島の平坦な並木道、そしてオビのデッキ通路とその手前です。普通のスニーカーでは足りません。アイゼンは必須でも、貸し出しでもありません。歩く距離は短く、問題は路面のほうです。"},{"question":"歩く距離は多いですか？","answer":"距離は多くありません — 難しいのは長さではなく路面です。雪岳山では入口近くの低い渓谷路のみを使い、登山も登頂もしません。南怡島は平坦で、半周すれば2時間でおよそ3 kmです。オビは短いデッキ通路です。ただしそのすべてが凍っているため、距離から想像されるより、時間と注意を多めに見てください。"},{"question":"お子さまや年配の方に向いていますか？","answer":"当社の他の日帰りツアーほどは向いておらず、どちらかが強く当てはまる場合は別のツアーをおすすめします。06:00発の13.5時間、厳冬の寒さ、そしてどの立ち寄り先も足元が凍っています。オビのデッキ通路はベビーカーや車椅子には適さず、氷壁の下は柵で仕切られています。雪が好きで、きちんとした服装のお子さまなら問題ありませんが、足元が不安な方には向きません。"},{"question":"当日に支払う費用はありますか？","answer":"はい、2種類あります。昼食はおよそ₩10,000〜15,000の各自負担です。オビでは村が少額の現地料金を徴収し、氷壁の見学エリアは1人あたり約₩1,000、そり滑りは別料金です。金額は地元で決められ、年ごとに変わりますので、少し現金をお持ちください。その日の金額はガイドが車内で確認します。雪岳山の公園入場は無料で、南怡島のフェリーと入場料はすでに含まれています。"},{"question":"なぜオビにはこんなに遅い時間に着くのですか？","answer":"場所のためです。オビ渓谷は加平南部にあり、雪岳山よりも南怡島よりもソウルに近いため、最後に訪れればバスはすでに家路を向いており、帰路も短く保てます。真冬の16:45到着は、氷に残る最後の日ざしと、そのあとに灯るデッキ照明を見られるということで、写真には良い時間帯です。ただし、訪問の中で最も冷える時間でもあるので、屋外でじっと立つ想定の服装でお越しください。"},{"question":"他の雪岳山ツアーとどう違いますか？","answer":"3か所目と季節です。当社の通年運行の雪岳山日帰りツアーは、国立公園に南怡島と晨静苑を組み合わせた、庭園中心で、どんな天候でも運行する穏やかな一日です。こちらはその庭園をオビの氷壁に入れ替えたもので、氷壁がある期間しか存在しません。1月・2月以外に旅行される方には、通年運行のルートのほうが向いています。"},{"question":"大雪になったらどうなりますか？","answer":"たいていはそのまま運行します — 冬季はバスに冬用タイヤを装着していますし、雪はむしろ目当てだからです。帰路は最大で1時間ほど長くかかるとお考えください。道路が閉鎖されるほどの降雪であれば出発を中止し、全額返金いたします。危険な状況で13.5時間の山岳日程を運行するより、中止を選びます。"}],"guestReviews":[],"reviewsSummary":{"averageRating":0,"totalReviews":0,"ratingDistribution":[{"stars":5,"count":0,"percentage":0},{"stars":4,"count":0,"percentage":0},{"stars":3,"count":0,"percentage":0},{"stars":2,"count":0,"percentage":0},{"stars":1,"count":0,"percentage":0}],"highlights":[]},"sticky_booking_bar":{"note":"冬季限定です — 日付を選択して氷壁の運営状況をご確認のうえ、ご予約を完了してください。","price":{"amountLabel":"69","currency":"USD","per":"person","salePriceUsd":69}},"pickup_dropoff":{"primary":{"name":"スターバックス 弘大入口駅 8番出口","address":"ソウル市麻浦区楊花路（弘大入口駅8番出口のスターバックス前）","time":"06:00 乗車 ／ 19:30 降車","instructions":"弘大入口駅8番出口を上がってすぐのスターバックス店舗前でガイドとお会いください。AtoC Koreaの看板と、乗車列に停まっているバスが目印です。"},"alternates":[{"name":"明洞駅 2番出口（ノースフェイス旗艦店）","address":"ソウル市中区退渓路（明洞駅2番出口のノースフェイス旗艦店）","time":"06:30 乗車 ／ 19:00 降車","instructions":"明洞駅2番出口を上がったところにあるノースフェイス旗艦店の前でガイドとお会いください。"}]},"matching_profile":{"profile_version":1,"is_active":true,"product_id":"seoul-winter-seoraksan-nami-eobi-ice-valley-day-tour","product_type":"bus","route_type":"fixed_route","destination_region":"seoul_gangwon","region_type":"gangwon_seoraksan","vehicle_type":"large_coach","duration_hours":13.5,"region_tags":["seoul_mapo","seoul_jung","gangwon_sokcho","gyeonggi_gapyeong"],"theme_tags":["national_park","mountain","buddhist_temple","k_drama_filming","themed_garden","hallyu_landmark"],"poi_tags":["seoraksan_national_park","nami_island","eobi_ice_valley"],"pace_level":0.7,"walking_level":0.6,"scenic_level":1,"photo_level":1,"culture_level":0.85,"relax_level":0.5,"first_time_fit":1,"family_fit":0.7,"senior_fit":0.5,"couple_fit":1,"solo_traveler_fit":0.9,"active_traveler_fit":0.85,"adult_family_fit":0.95,"family_with_teens_fit":0.95,"young_kids_fit":0.5,"senior_active_fit":0.75,"senior_general_fit":0.55,"mobility_friendly_fit":0.4,"stroller_fit":0.2,"one_day_fit":1,"same_day_flight_fit":0.1,"rain_fit":0.3,"value_for_money_fit":1,"iconic_landmark_fit":1,"cafe_fit":0.5,"food_fit":0.5,"nature_fit":1,"beach_fit":0.1,"nightlife_fit":0.1,"shopping_fit":0.25,"no_shopping_fit":1,"local_culture_fit":0.7,"storytelling_fit":0.9,"unesco_fit":0.55,"intangible_heritage_fit":0.5,"indoor_ratio":0.1,"weather_sensitivity":"high","comfort_level":0.55,"budget_fit":1,"premium_fit":0.2,"small_group_fit":0.15,"private_fit":0.05,"bus_fit":1,"price_band":"budget","pickup_base":"seoul_central","return_time_band":"19:00-19:30","duration_band":"13h","min_recommended_age":8,"hard_constraints":{"avoidIf":["mobility_limited","wheelchair_required"],"notIdealFor":["very_low_mobility","young_kids_under_6"]},"walking_notes":["13.5-hour day with ~4-5 km total walking.","Seoraksan paths rocky in places; Nami Island flat; the Eobi Valley deck path is short but icy.","Non-slip winter footwear essential; the ground under the ice wall is closed off.","Cable car at Seoraksan optional, weather-dependent and not included."],"keywords":["seoul seoraksan day tour","nami island day trip","garden of morning calm tour","seoul winter wonder tour","seoraksan nami one day"],"synonym_hints":["seoul to seoraksan day tour","korea three signature stops day trip","seoul winter sonata tour"],"seasonality":"winter_only","pickup_base_normalized":"seoul","vehicle_type_legacy":"bus_coach","anchor_poi_keys":["seoraksan_national_park","nami_island","eobi_ice_valley"],"private_tour_fit":0.05,"customizable_route_fit":0.05,"flexibility_fit":0.2,"fixed_itinerary_fit":1,"national_park_fit":1,"buddhist_temple_fit":0.6,"k_drama_filming_fit":1,"winter_sonata_fit":1,"themed_garden_fit":0,"history_culture_fit":0.65,"religious_history_fit":0.45,"premium_dining_fit":0.15,"seasonal_fit":1,"winter_lighting_festival_fit":0,"autumn_foliage_fit":0,"china_mainland_market_fit":0.85,"korea_domestic_market_fit":0,"taiwan_market_fit":1,"singapore_market_fit":1,"hong_kong_market_fit":1,"china_diaspora_overseas_market_fit":1,"se_asia_market_fit":1,"us_market_fit":0.95,"europe_market_fit":0.95,"australia_market_fit":0.95,"japan_market_fit":1,"first_time_korea_fit":1,"seoul_day_trip_fit":1,"english_speaking_guide_provided":true,"chinese_speaking_guide_available_on_advance_notice":true,"japanese_speaking_guide_available_on_advance_notice":true},"matching_metadata":{"primary_themes":["winter","seasonal","seoul_day_trip","national_park","ice_wall","k_drama_filming"],"secondary_themes":["frozen_waterfall","snow_scenery","winter_sonata","metasequoia_lane","photo_spots","first_time_korea"],"best_for":["winter_travelers","photo_lovers","couples","first_time_korea","snow_seekers"],"not_recommended_for":["travelers_sensitive_to_cold","minimal_walking_seekers","visitors_outside_dec_to_feb"],"anchor_pois":["Seoraksan National Park","Nami Island","Eobi Ice Valley"],"anchor_poi_keys":["seoraksan_national_park","nami_island","eobi_ice_valley"],"competing_products":["seoul-seoraksan-nami-island-morning-calm-day-tour","seoul-seoraksan-national-park-sokcho-beach-day-trip","seoul-seoraksan-naksansa-temple-naksan-beach-day-trip"],"reviews_attribution":"New product (2026-08) — no imported reviews; rating starts at 0.","unesco_fit_note":"Seoraksan is Korea''s first UNESCO Biosphere Reserve (1982) and a UNESCO World Heritage tentative site, but no stop on this route is an inscribed Wor